/// 基于过滤器关键字二分检索 Wireshark 官方 3,157 条规约定义 (时间复杂度: O(log2 N) ≈ 12 次比较)
pub fn lookup_official_protocol(filter_name: &str) -> Option<&'static OfficialProtocolDefinition> {
    if filter_name.is_empty() {
        return None;
    }
    let lower = filter_name.to_ascii_lowercase();
    match FULL_PROTOCOL_CATALOG.binary_search_by(|p| p.filter_name.cmp(&lower.as_str())) {
        Ok(idx) => Some(&FULL_PROTOCOL_CATALOG[idx]),
        Err(_) => None,
    }
}

/// 基于端口号二分检索 6,160 条 IANA / Wireshark 官方服务端口 (时间复杂度: O(log2 N) ≈ 13 次比较)
pub fn lookup_official_service_port(port: u16) -> Option<&'static OfficialServicePortDefinition> {
    if port == 0 {
        return None;
    }
    match FULL_SERVICE_PORT_CATALOG.binary_search_by_key(&port, |p| p.port) {
        Ok(idx) => Some(&FULL_SERVICE_PORT_CATALOG[idx]),
        Err(_) => None,
    }
}
